import { Pipe, PipeTransform } from "@angular/core";
import { CalendarDate } from "../calendar-date";
import { Week } from "../calendar.model";

@Pipe({
  name: 'calendarBuilder',
  pure: true,
  standalone: true,
}) export class CalendarBuilderPipe implements PipeTransform {

  transform(monthIndex: number, year: number, firstDayOfWeekIndex: number) {
    return this.buildMonth(monthIndex, year, firstDayOfWeekIndex);
  }

  private buildMonth(monthIndex: number, year: number, firstDayOfWeekIndex: number): Week[] {
    const firstDayOfMonth = new CalendarDate(year, monthIndex, 1);
    const lastDayOfMonth = new CalendarDate(year, monthIndex, firstDayOfMonth.getDaysInMonth());
    const month: Week[] = [];

    for (
      let date = firstDayOfMonth;
      date.isSameOrBefore(lastDayOfMonth);
      date = date.clone().addDays(1)
    ) {
      let currentWeek = month[month.length - 1];
      if (!currentWeek || (date.getDayOfWeek() === firstDayOfWeekIndex)) {
        currentWeek = [];
        month.push(currentWeek);
      }
      currentWeek.push({
        date,
        dayNumber: date.getDate(),
        id: date.getTime().toString()
      });
    }
    return month;
  }
}

import { Pipe, PipeTransform } from "@angular/core";
import { DaysOfTheWeek} from "../calendar.model";

@Pipe({
  name: 'daysOfTheWeek',
  pure: true,
  standalone: true,
}) export class DaysOfTheWeekPipe implements PipeTransform {

  transform(daysOfTheWeek: DaysOfTheWeek, firstDayOfWeekIndex: number) {
    const days = [...daysOfTheWeek];
    return days.concat(days.splice(0, firstDayOfWeekIndex))
  }
}

import { Pipe, PipeTransform } from "@angular/core";
import { Day } from "../calendar.model";
import { CalendarDate } from "../calendar-date";

@Pipe({
  name: 'dayStatus',
  pure: true,
  standalone: true,
}) export class DayStatusPipe implements PipeTransform {

  transform({date}: Day, selected?: CalendarDate[]): string {
    const isSelected = selected?.some((d)=>d.isSame(date));
    const orderedDates = selected ? [...selected].sort((d, b)=>d.isSameOrBefore(b) ? -1 : 1) : selected;

    if (orderedDates?.[0] && orderedDates[1]) {
      const inRange = date.isBefore(orderedDates[1]) && date.isAfter(orderedDates[0]);
      if(inRange) {
        return 'interval';
      }
    }

    if(isSelected) {
      return 'selected';
    }

    return 'default';
  }
}

