import { Component } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { AsyncPipe, JsonPipe, NgFor } from '@angular/common';
import { UiButtonComponent } from '../../projects/brocol-ui/src/lib/components/button/button.component';
import { FormControl, ReactiveFormsModule, Validators } from '@angular/forms';
import { CalendarDate, UI_CALENDAR_SELECTION_STRATEGY, UiCalendarMonthComponent, UiCalendarSelectionStrategy } from '../../projects/brocol-ui/src/public-api';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [AsyncPipe, RouterOutlet, UiButtonComponent, UiCalendarMonthComponent, NgFor, JsonPipe, ReactiveFormsModule],
  templateUrl: './app.component.html',
  styleUrl: './app.component.scss',
  providers: [
    {
      provide: UI_CALENDAR_SELECTION_STRATEGY,
      useExisting: AppComponent
    }
  ]
})
export class AppComponent implements UiCalendarSelectionStrategy {
  onSelect(newSelection: CalendarDate, selectedDays: CalendarDate[] = []): CalendarDate[] {
    console.info('this.mode.value', this.mode.value);
    if(this.mode.value === 1 || selectedDays.length >= 2) {
      return [newSelection];
    }

    if(selectedDays[0].isSame(newSelection)) {
      return [newSelection, newSelection];
    }
    
    if(newSelection.isBefore(selectedDays[0])) {
      return [newSelection, selectedDays[0]];
    }

    if(newSelection.isAfter(selectedDays[0])) {
      return [selectedDays[0], newSelection];
    }
  
    return selectedDays;
  }

  get selectedFirstDayOfweek() {
    return <number>this.firstDayOfWeek.value;
  }

  title = 'angular-forms';
  selectedDate = [CalendarDate.parseDateAsLocalTime(new Date())];
  monthIndex = this.selectedDate[0].getMonth();
  firstDayOfWeek = new FormControl(1, Validators.required);
  mode = new FormControl(1, Validators.required);

  options = ["Domingo", "Lunes", "Martes", "Miercoles", "Jueves", "Viernes", "Sabado"];

  get selectedDates() {
    return this.selectedDate.map((date)=>date.toISOString());
  }
}

import { ChangeDetectionStrategy, Component, HostBinding, HostListener, Input, booleanAttribute } from "@angular/core";
import { UiRippleDirective } from "./ripple.directive";

@Component({
  selector: 'button[ui-button], a[ui-button]',
  styleUrl: './button.component.scss',
  templateUrl: './button.component.html',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  hostDirectives: [UiRippleDirective],
})
export class UiButtonComponent {
  @Input({ transform: booleanAttribute }) disabledInteractive = false;
  @Input({ transform: booleanAttribute }) disabled = false;

  @HostBinding('attr.aria-disabled') protected get _ariaDisabled() {
    return (this.disabled && this.disabledInteractive) || null;
  }

  @HostBinding('attr.disabled') protected get _disabled() {
    return (this.disabled && !this.disabledInteractive) || null;
  }

  @HostListener('click', ["$event"]) protected onClick(event: MouseEvent) {
    if (this.disabled) {
      event.stopImmediatePropagation();
      event.preventDefault();
    }
  }
}

import { NgClass, NgFor, NgIf } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  inject,
  Input,
  Output,
} from '@angular/core';
import { CalendarDate } from '../calendar-date';
import { Day, DaysOfTheWeek } from '../calendar.model';
import { CalendarBuilderPipe } from './calendar-builder.pipe';
import { DaysOfTheWeekPipe } from './days-of-week.pipe';
import { UI_CALENDAR_SELECTION_STRATEGY } from '../calendar.config';
import { DayStatusPipe } from './calendar-status.pipe';

@Component({
  selector: 'ui-calendar-month',
  templateUrl: './calendar-month.component.html',
  styleUrls: ['./calendar-month.component.scss'],
  imports: [NgFor, CalendarBuilderPipe, DaysOfTheWeekPipe, DayStatusPipe, NgIf, NgClass],
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class UiCalendarMonthComponent {
  @Input() monthIndex: number = new Date().getMonth(); 
  @Input() year: number = new Date().getFullYear();
  @Input() firstDayOfWeek = 0; // 0 => Sunday
  @Input() weekDaysNames: DaysOfTheWeek = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
  @Input() selected?: CalendarDate[];
  @Output() selectedChange = new EventEmitter<CalendarDate[]>();

  private selectionStrategy = inject(UI_CALENDAR_SELECTION_STRATEGY);

  protected trackDaysBy(_: number, day: Day) {
    return day.id;
  }

  protected selectDay({date}: Day) {
    this.selected = this.selectionStrategy.onSelect(date, this.selected);
    this.selectedChange.emit(this.selected);
  }
}

