%buttonReset {
    --webkit-appearance: none;
    border-radius: 0;
    text-align: inherit;
    background: none;
    box-shadow: none;
    padding: 0;
    cursor: pointer;
    border: none;
    color: inherit;
    font: inherit;
}

:host {
    --cell-height: 24px;
    --cell-width: 24px;
    --button-border-radius: 2px;
    --button-selected-background: var(--color-dark-blue);
    --button-selected-color: var(--color-white);
    --button-interval-background: var(--color-blue);
    --button-interval-color: var(--color-white);
    --button-interval-opacity: 0.5;
}

th,
td {
    height: var(--cell-height);
    width: var(--cell-width);
}

button {
    @extend %buttonReset;

    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--button-border-radius);
    width: 100%;
    height: 100%;
}

.selected {
    background: var(--button-selected-background);
    color: var(--button-selected-color);
}

.interval {
    border-radius: 0;
    background: var(--button-interval-background);
    color: var(--button-interval-color);
    opacity: var(--button-interval-opacity);
}

table {
    table-layout: fixed;
    border-collapse: collapse;
    border:unset;
    min-width: max-content;
}

